struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    uint laneId = WaveGetLaneIndex();
    uint laneCount = WaveGetLaneCount();
    float laneValue = sin(float(laneId) * 0.5 + t);
    float waveSum = WaveActiveSum(laneValue);
    float waveAvg = waveSum / float(laneCount);
    float normLane = float(laneId) / float(max(1u, laneCount - 1u));
    float3 laneColor = 0.5 + 0.5 * sin(float3(0, 2, 4) + normLane * 6.28);
    float brightness = 0.3 + 0.7 * saturate(waveAvg * 0.5 + 0.5);
    float3 col = laneColor * brightness;
    float border = smoothstep(0.0, 0.01, frac(i.uv.x * float(laneCount)));
    col *= 0.7 + 0.3 * border;
    return float4(col, 1.0);
}
